def all_transforms(p, reflect=False):
    tfs=[]
    for k in range(4):
      for f in ([1,-1] if reflect else [1]):
       def tf(x,y,k=k,f=f):
        x*=f
        for _ in range(k): x,y=y,-x
        return x,y
       raw={tf(x,y):v for (x,y),v in p.items()}
       mx=min(x for x,y in raw);my=min(y for x,y in raw)
       norm={(x-mx,y-my):v for (x,y),v in raw.items()}
       key=tuple(sorted(norm.items()))
       if key not in [t[0] for t in tfs]: tfs.append((key,norm))
    return [d for k,d in tfs]
def make_oriented_placements(reflect=False):
