def getcomps_conn(G,rs,cs,bg,conn=8):
 seen=set();res=[]
 deltas=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0) and (conn==8 or abs(dr)+abs(dc)==1)]
 for r in rs:
  for c in cs:
   if G[r][c]!=bg and (r,c) not in seen:
    st=[(r,c)];seen.add((r,c));pts=[]
    while st:
     x,y=st.pop();pts.append((x,y,G[x][y]))
     for dx,dy in deltas:
      a,b=x+dx,y+dy
      if a in rs and b in cs and G[a][b]!=bg and (a,b) not in seen:seen.add((a,b));st.append((a,b))
    x0=min(x for x,y,v in pts);y0=min(y for x,y,v in pts)
    res.append({(x-x0,y-y0):v for x,y,v in pts})
 return res
